export type OrientationValue = 'portrait' | 'landscape';
export interface IOrientationState {
    value: OrientationValue;
    isLandscape: boolean;
    isPortrait: boolean;
    isInverted: boolean;
    isChanging: boolean;
}
export interface OrientationEvents {
    onOrientationStateChanged: (state: IOrientationState) => void;
    onResize: () => void;
}
